create table public.job_message_attachments(id uuid primary key default gen_random_uuid(),message_id uuid not null references public.job_messages on delete restrict,job_id uuid not null references public.jobs on delete restrict,uploaded_by uuid not null references public.profiles on delete restrict,storage_path text not null unique,mime_type text not null check(mime_type in ('image/jpeg','image/png','image/webp','application/pdf')),byte_size bigint not null check(byte_size between 1 and 10485760),created_at timestamptz not null default now());
create index job_message_attachments_job_idx on public.job_message_attachments(job_id,created_at,id);alter table public.job_message_attachments enable row level security;
create policy "participants read authorized message attachments" on public.job_message_attachments for select to authenticated using(exists(select 1 from public.job_messages m where m.id=message_id and public.can_read_job_message(m.job_id,m.channel)));
grant select on public.job_message_attachments to authenticated;revoke insert,update,delete on public.job_message_attachments from authenticated;
create trigger immutable_job_message_attachments before update or delete on public.job_message_attachments for each row execute function public.prevent_event_mutation();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('conversation-attachments','conversation-attachments',false,10485760,array['image/jpeg','image/png','image/webp','application/pdf']) on conflict(id) do update set public=false,file_size_limit=10485760,allowed_mime_types=excluded.allowed_mime_types;
create policy "conversation participants upload attachment objects" on storage.objects for insert to authenticated with check(bucket_id='conversation-attachments' and (storage.foldername(name))[1]=auth.uid()::text and (public.owns_job(((storage.foldername(name))[2])::uuid) or public.provider_has_assigned_job(((storage.foldername(name))[2])::uuid) or public.crew_has_assigned_job(((storage.foldername(name))[2])::uuid) or public.has_any_role(array['dispatcher','super_admin']::public.app_role[])));
create policy "conversation participants read attachment objects" on storage.objects for select to authenticated using(bucket_id='conversation-attachments' and exists(select 1 from public.job_message_attachments a join public.job_messages m on m.id=a.message_id where a.storage_path=name and public.can_read_job_message(m.job_id,m.channel)));
create policy "uploaders remove unregistered attachment objects" on storage.objects for delete to authenticated using(bucket_id='conversation-attachments' and owner_id=auth.uid()::text and not exists(select 1 from public.job_message_attachments a where a.storage_path=name));
create or replace function public.post_job_message_attachment(p_job uuid,p_channel text,p_body text,p_path text,p_mime text,p_size bigint,p_request_id uuid) returns uuid language plpgsql security definer set search_path=public,storage as $$declare v_message uuid;v_attachment uuid;begin if p_mime not in ('image/jpeg','image/png','image/webp','application/pdf') or p_size not between 1 and 10485760 or p_path not like auth.uid()::text||'/'||p_job::text||'/%' then raise exception 'invalid attachment';end if;if not exists(select 1 from storage.objects where bucket_id='conversation-attachments' and name=p_path and owner_id=auth.uid()::text) then raise exception 'attachment object not found';end if;v_message:=public.post_job_message(p_job,p_channel,p_body,p_request_id);select id into v_attachment from public.job_message_attachments where message_id=v_message;if v_attachment is not null then return v_attachment;end if;insert into public.job_message_attachments(message_id,job_id,uploaded_by,storage_path,mime_type,byte_size) values(v_message,p_job,auth.uid(),p_path,p_mime,p_size) returning id into v_attachment;insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata,request_id) values(auth.uid(),'job_message.attachment_added','job_message_attachment',v_attachment,jsonb_build_object('job_id',p_job,'message_id',v_message,'mime_type',p_mime,'byte_size',p_size),p_request_id);return v_attachment;end $$;
revoke all on function public.post_job_message_attachment(uuid,text,text,text,text,bigint,uuid) from public;grant execute on function public.post_job_message_attachment(uuid,text,text,text,text,bigint,uuid) to authenticated;
create or replace function public.get_job_message_attachments(p_job uuid) returns table(id uuid,message_id uuid,mime_type text,byte_size bigint,created_at timestamptz) language sql stable security definer set search_path=public as $$select a.id,a.message_id,a.mime_type,a.byte_size,a.created_at from public.job_message_attachments a join public.job_messages m on m.id=a.message_id where a.job_id=p_job and public.can_read_job_message(m.job_id,m.channel) order by a.created_at,a.id$$;
revoke all on function public.get_job_message_attachments(uuid) from public;grant execute on function public.get_job_message_attachments(uuid) to authenticated;
